def computepay(hours, rate):
    """Calculates gross pay including overtime pay (1.5x after 40 hrs)."""
    if hours > 40:
        reg_pay = 40 * rate
        overtime_pay = (hours - 40) * (rate * 1.5)
        return reg_pay + overtime_pay
    else:
        return hours * rate

